function mountStatus(container, animationData, reducedMotion) {
  const player = lottie.loadAnimation({
    container, renderer: 'svg', animationData,
    loop: false, autoplay: !reducedMotion,
  });
  if (reducedMotion) player.goToAndStop(0, true);
  return () => player.destroy();
}

function mountCanvas(canvas, animationData, reducedMotion) {
  const player = new DotLottie({
    canvas, data: JSON.stringify(animationData),
    loop: false, autoplay: !reducedMotion,
  });
  return () => player.destroy();
}

import Animated, { ReduceMotion, useAnimatedStyle, useSharedValue, withTiming } from 'react-native-reanimated';
import { Button, View } from 'react-native';

export function SlideFeedback() {
  const offset = useSharedValue(0);
  const style = useAnimatedStyle(() => ({ transform: [{ translateX: offset.value }] }));
  return <View>
    <Button title="Move indicator" onPress={() => {
      offset.value = withTiming(offset.value === 0 ? 24 : 0,
        { duration: 180, reduceMotion: ReduceMotion.System });
    }} />
    <Animated.View accessibilityLabel="Position indicator" style={[{ width: 20, height: 20, backgroundColor: '#174' }, style]} />
  </View>;
}

function SlowSpin({ reducedMotion }: { reducedMotion: boolean }) {
  const mesh = useRef<THREE.Mesh>(null!);
  useFrame((_, delta) => {
    if (!reducedMotion) mesh.current.rotation.y += Math.min(delta, 0.1) * 0.2;
  });
  return <mesh ref={mesh}><boxGeometry /><meshStandardMaterial /></mesh>;
}
// Surround with an HTML description; imports are from React, three, and @react-three/fiber.
<Canvas frameloop={reducedMotion ? 'demand' : 'always'} dpr={[1, 1.5]}>
  <ambientLight /><SlowSpin reducedMotion={reducedMotion} />
</Canvas>

