import { useEffect } from 'react';
import { useRive } from '@rive-app/react-canvas';

function LocalFeedback({ buffer, reducedMotion }) {
  const { rive, RiveComponent } = useRive({ buffer, autoplay: !reducedMotion });
  useEffect(() => {
    if (!rive) return;
    if (reducedMotion) rive.pause();
    else rive.play();
  }, [rive, reducedMotion]);
  return <div aria-hidden="true"><RiveComponent /></div>;
}

// Integration fragment: controller is available only after RiveLoaded.
void updatePlayback(BuildContext context) {
  final reduce = MediaQuery.of(context).disableAnimations;
  controller.active = userRequestedPlayback && !reduce;
}

